function visibleBoneRects(){const rect=viewport.getBoundingClientRect(),boxes=[];for(const m of meshes){const b=m.geometry.boundingBox.clone().applyMatrix4(m.matrix),pts=[];for(let i=0;i<8;i++){const p=new T.Vector3(i&1?b.max.x:b.min.x,i&2?b.max.y:b.min.y,i&4?b.max.z:b.min.z).project(camera);if(p.z>=-1&&p.z<=1)pts.push([(p.x*.5+.5)*rect.width,(.5-p.y*.5)*rect.height]);}if(pts.length===8){const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);boxes.push({x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)});}}return boxes;}
